const SETTINGS_DEFAULT={capacity:25,weekly_rate:5,historical_completed:53};
const DEMO_CASES=[{id:'11111111-1111-4111-8111-111111111111',ref:'CC-261101',client_name:'Sample Collector',owner_email:'collector@example.com',card_name:'Rayquaza ★',set_name:'EX Deoxys',card_number:'107/107',card_year:'2005',market_value:1800,declared_value:2000,treatment_codes:['dent','edge'],quote_amount:135,quote_notes:'Sample quote pending in-hand confirmation.',quote_status:'issued',stage:7,closed_at:null,created_at:'2026-11-06T05:00:00Z',updated_at:'2026-11-09T09:00:00Z',notes:'Illustrative demonstration record only.'},{id:'22222222-2222-4222-8222-222222222222',ref:'CC-261102',client_name:'Sample Collector',owner_email:'collector@example.com',card_name:'Charizard',set_name:'Base Set',card_number:'4/102',card_year:'1999',market_value:700,declared_value:850,treatment_codes:['crease'],quote_amount:84,quote_notes:'Risks require approval.',quote_status:'issued',stage:5,closed_at:null,created_at:'2026-11-05T05:00:00Z',updated_at:'2026-11-07T03:00:00Z',notes:'Example of a high-risk crease case.'},{id:'33333333-3333-4333-8333-333333333333',ref:'CC-261103',client_name:'Preview Client',owner_email:'sample@example.com',card_name:'Pikachu Promo',set_name:'Illustrative Promo',card_number:'001',card_year:'2024',market_value:100,declared_value:100,treatment_codes:['surface'],quote_amount:25,quote_notes:'',quote_status:'approved',stage:10,closed_at:null,created_at:'2026-11-03T05:00:00Z',updated_at:'2026-11-10T05:00:00Z',notes:''}];
const DEMO_UPDATES=[{case_id:DEMO_CASES[0].id,stage:1,message:'Sample case registered',created_at:'2026-11-06T05:00:00Z'},{case_id:DEMO_CASES[0].id,stage:5,message:'Initial quote shared',created_at:'2026-11-08T05:00:00Z'},{case_id:DEMO_CASES[0].id,stage:7,message:'Treatment scheduled',created_at:'2026-11-09T09:00:00Z'},{case_id:DEMO_CASES[1].id,stage:5,message:'Quote issued with treatment risks',created_at:'2026-11-07T03:00:00Z'}];
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
